<script setup>
import { computed, onUnmounted, ref } from 'vue'; import {tmjPresets,analyzeVibration} from '../engines/tmjVibroarthrometryEngine.js';
const emit=defineEmits(['save']);const preset=ref(tmjPresets[0]);const side=ref('Left');const motion=ref(43);const micActive=ref(false);const micError=ref('');const liveBands=ref(null);let stream=null,context=null,analyser=null,raf=0;
const startMic=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});context=new AudioContext();analyser=context.createAnalyser();analyser.fftSize=2048;context.createMediaStreamSource(stream).connect(analyser);micActive.value=true;micError.value='';readMic()}catch{micError.value='Microphone unavailable or permission denied.'}};
const readMic=()=>{if(!micActive.value)return;const bins=new Uint8Array(analyser.frequencyBinCount);analyser.getByteFrequencyData(bins);let lo=0,hi=0;for(let i=0;i<bins.length;i++){const f=i*context.sampleRate/analyser.fftSize;if(f>=20&&f<300)lo+=bins[i]**2;if(f>=300&&f<=1200)hi+=bins[i]**2}liveBands.value={low:Math.sqrt(lo),high:Math.sqrt(hi),duration:20};raf=requestAnimationFrame(readMic)};
const stopMic=()=>{cancelAnimationFrame(raf);stream?.getTracks().forEach(t=>t.stop());context?.close();stream=null;context=null;analyser=null;micActive.value=false;liveBands.value=null};onUnmounted(stopMic);
const result=computed(()=>liveBands.value?analyzeVibration(liveBands.value.low,liveBands.value.high,liveBands.value.duration):analyzeVibration(preset.value.low,preset.value.high,preset.value.duration));
const path=computed(()=>Array.from({length:72},(_,i)=>{const x=i/71;const wave=Math.sin(i*.56)*(.17+result.value.ratio*.18)+Math.sin(i*1.34)*result.value.ratio*.12;return `${i===0?'M':'L'} ${x*100} ${52+wave*70}`}).join(' '));
</script>
<template><section class="module-card glass"><div class="module-head"><div><div class="eyebrow">02 / Jaw motion & acoustic patterns</div><h2>TMJ vibration lab</h2><p>Compare synthetic vibration patterns and record jaw range-of-motion observations. A phone microphone cannot diagnose disc displacement or arthritis.</p></div><span class="badge">EDUCATIONAL SIMULATOR</span></div><div class="two-col"><div><div class="inner"><div class="control-row"><strong>Clinical pattern</strong><select class="select" style="width:60%" v-model="preset" :value="preset.name"><option v-for="p in tmjPresets" :key="p.name" :value="p">{{p.name}}</option></select></div><div class="chart-wrap"><svg class="chart" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M0 25H100M0 50H100M0 75H100" stroke="#ffffff14"/><path :d="path" fill="none" stroke="#73e6d2" stroke-width="1.2" vector-effect="non-scaling-stroke"/><text x="4" y="12" class="chart-label">SYNTHETIC SPECTRAL ENVELOPE</text></svg></div><div class="split" style="margin-top:10px"><button class="action" @click="micActive?stopMic():startMic()">{{micActive?'Stop microphone':'Use microphone'}}</button><span class="small">{{micActive?'Live spectrum · raw mic settings requested':'Preset signal'}}</span></div><p v-if="micError" class="error">{{micError}}</p><div class="legend"><span><i></i>Low band · {{micActive?result.total:preset.low}} relative energy</span><span style="color:#bc9dff"><i style="background:#bc9dff"></i>High band · {{micActive?result.ratio:preset.high}} ratio</span></div><div class="metric-grid"><div class="metric"><span>High / low</span><b>{{result.ratio}}</b></div><div class="metric"><span>Opening</span><b>{{preset.opening}} mm</b></div><div class="metric"><span>Pattern</span><b style="font-size:12px">{{result.label}}</b></div></div></div><div class="inner" style="margin-top:12px"><h3>Jaw movement guide</h3><div class="control-row"><span class="small">Side</span><div class="split"><button class="action secondary" :class="{active:side==='Left'}" @click="side='Left'">Left</button><button class="action secondary" @click="side='Right'">Right</button></div></div><div class="control-row"><span class="small">Maximum opening</span><b class="mono">{{motion}} mm</b></div><input class="range" type="range" min="10" max="55" v-model.number="motion"><p class="footnote">Reference ranges vary by person and protocol. Stop if movement causes pain or locking.</p><button class="action" @click="emit('save',{module:'tmj_jva_studies',side,opening:motion,pattern:preset.name,ratio:result.ratio})">Save study</button></div></div><div><div class="inner"><h3>Guided open · close arc</h3><svg viewBox="0 0 300 180" style="width:100%;height:180px"><path d="M42 135 Q145 5 258 135" fill="none" stroke="#76ead4" stroke-width="2" stroke-dasharray="5 6"/><path d="M42 136H258" stroke="#ffffff20"/><circle cx="150" cy="62" r="8" fill="#b29bff"/><text x="104" y="165" fill="#91a0a7" font-size="10">INTER-INCISAL OPENING</text><text x="126" y="45" fill="#d4fff5" font-size="11">{{motion}} mm</text></svg><div class="risk"><strong>{{preset.stage}}</strong><p>Opening measurement and acoustic pattern are simulated. Seek a dentist or clinician for persistent pain, locking, or limited motion.</p></div></div><div class="notice" style="margin-top:12px">This is not a medical device. It does not identify a TMJ condition or assign a Piper stage.</div></div></div></section></template>
